package contract

import (
	"context"
	"time"
)

// Diagnostics is an internal, text-free observation of one actual pipeline.
// RequestID is generated by that pipeline; it is not an authorization token.
// Mode is empty on failure, including a failed final serving recheck.
type Diagnostics struct {
	RequestID, ProjectID, AgentID string
	Domain                        SourceKind
	QuerySHA256                   string
	QueryBytes                    int
	Backend                       string
	Mode                          Mode
	LexicalCandidates             int
	DenseCandidates               int
	FusionCandidates              int
	ResultCount                   int
	RerankUsed                    bool
	DegradationReason             string
	ErrorCode                     string
	Lexical, Embedding, Dense     time.Duration
	Fusion, Total                 time.Duration
}

// Observer must be a synchronous, nonblocking diagnostics sink. It receives no
// query, result content, raw error, SQL, credential or business authority.
type Observer interface {
	ObserveRetrieval(context.Context, Diagnostics)
}

// DiagnosticProvider describes the backend already selected by the authorized
// provider. It is called only after ValidateServing succeeds. It neither grants
// authority nor changes the retrieval request or its failure policy.
type DiagnosticProvider interface {
	DiagnosticBackend(context.Context, Request) string
}
